//	DO NOTHING 返回 0 行 = 这条事件已经处理过，直接返回成功，不要重复入账。
func (q *Queries) InsertWebhookEvent(ctx context.Context, arg InsertWebhookEventParams) (WebhookEvent, error) {
	row := q.db.QueryRow(ctx, insertWebhookEvent,
		arg.Gateway,
		arg.EventID,
		arg.EventType,
		arg.PayloadHash,
		arg.RawBody,
		arg.SignatureOk,
	)
	var i WebhookEvent
	err := row.Scan(
		&i.ID,
		&i.Gateway,
		&i.EventID,
		&i.EventType,
		&i.PayloadHash,
		&i.RawBody,
		&i.SignatureOk,
		&i.ProcessedAt,
		&i.Error,
		&i.ReceivedAt,
	)
	return i, err
}

