const listWatchedPaymentAddresses = `-- name: ListWatchedPaymentAddresses :many
SELECT id, trade_no, user_id, pay_chain, pay_address, pay_amount_raw, status, address_watch_until
FROM orders
WHERE pay_address IS NOT NULL
  AND address_watch_until > now()
ORDER BY address_watch_until
`

type ListWatchedPaymentAddressesRow struct {
	ID                int64              `json:"id"`
	TradeNo           string             `json:"trade_no"`
	UserID            int64              `json:"user_id"`
	PayChain          *string            `json:"pay_chain"`
	PayAddress        *string            `json:"pay_address"`
	PayAmountRaw      pgtype.Numeric     `json:"pay_amount_raw"`
	Status            OrderStatus        `json:"status"`
	AddressWatchUntil pgtype.Timestamptz `json:"address_watch_until"`
}

// 过期订单继续监听收款地址 ≥ 24h（user-journey §7）。到账后入账为**余额**而不是直接开通
// —— 余额仅可消费不可提现，这个兜底在资金合规上是安全的。
// 不做这一条，用户第一次付款的钱就真的进黑洞。
// ⚠️ 走 orders_addr_watch_idx；索引谓词里不能有 now()（非 IMMUTABLE），
//
//	所以过滤条件写在 WHERE 里走范围扫描。
func (q *Queries) ListWatchedPaymentAddresses(ctx context.Context) ([]ListWatchedPaymentAddressesRow, error) {
	rows, err := q.db.Query(ctx, listWatchedPaymentAddresses)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListWatchedPaymentAddressesRow{}
	for rows.Next() {
		var i ListWatchedPaymentAddressesRow
		if err := rows.Scan(
			&i.ID,
			&i.TradeNo,
			&i.UserID,
			&i.PayChain,
			&i.PayAddress,
			&i.PayAmountRaw,
			&i.Status,
			&i.AddressWatchUntil,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

