const updateOrderStatus = `-- name: UpdateOrderStatus :one
UPDATE orders SET
  status = $2,
  paid_at      = CASE WHEN $2::order_status IN ('paid','completed') THEN coalesce(paid_at, now()) ELSE paid_at END,
  completed_at = CASE WHEN $2::order_status = 'completed' THEN coalesce(completed_at, now()) ELSE completed_at END,
  cancelled_at = CASE WHEN $2::order_status IN ('cancelled','expired') THEN coalesce(cancelled_at, now()) ELSE cancelled_at END,
  updated_at = now()
WHERE id = $1
RETURNING id, trade_no, user_id, type, plan_id, period, status, currency, amount_gross, amount_discount, surplus_amount, amount_balance, amount_due, amount_paid, amount_refunded, surplus_order_ids, coupon_id, invited_by, gateway, gateway_ref, pay_chain, pay_address, pay_amount_raw, pay_amount_received, fx_usdt_per_cny, fx_locked_at, expires_at, address_watch_until, paid_at, completed_at, cancelled_at, created_at, updated_at
`

type UpdateOrderStatusParams struct {
	ID     int64       `json:"id"`
	Status OrderStatus `json:"status"`
}

// 状态迁移。⚠️ 调用方必须在同一事务里 InsertOrderTransition —— 状态机没有触发器兜底，
// 漏写审计不会报错（这与 user_rev 不同：那里漏了是静默故障，这里漏了是证据缺失）。
func (q *Queries) UpdateOrderStatus(ctx context.Context, arg UpdateOrderStatusParams) (Order, error) {
	row := q.db.QueryRow(ctx, updateOrderStatus, arg.ID, arg.Status)
	var i Order
	err := row.Scan(
		&i.ID,
		&i.TradeNo,
		&i.UserID,
		&i.Type,
		&i.PlanID,
		&i.Period,
		&i.Status,
		&i.Currency,
		&i.AmountGross,
		&i.AmountDiscount,
		&i.SurplusAmount,
		&i.AmountBalance,
		&i.AmountDue,
		&i.AmountPaid,
		&i.AmountRefunded,
		&i.SurplusOrderIds,
		&i.CouponID,
		&i.InvitedBy,
		&i.Gateway,
		&i.GatewayRef,
		&i.PayChain,
		&i.PayAddress,
		&i.PayAmountRaw,
		&i.PayAmountReceived,
		&i.FxUsdtPerCny,
		&i.FxLockedAt,
		&i.ExpiresAt,
		&i.AddressWatchUntil,
		&i.PaidAt,
		&i.CompletedAt,
		&i.CancelledAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

