const upsertWalletBalance = `-- name: UpsertWalletBalance :one
INSERT INTO wallet_balances (user_id, currency, balance, last_entry_id, updated_at)
VALUES ($1, $2, $3, $4, now())
ON CONFLICT (user_id) DO UPDATE SET
  balance = wallet_balances.balance + EXCLUDED.balance,
  last_entry_id = EXCLUDED.last_entry_id,
  updated_at = now()
RETURNING user_id, currency, balance, last_entry_id, updated_at
`

type UpsertWalletBalanceParams struct {
	UserID      int64  `json:"user_id"`
	Currency    string `json:"currency"`
	Balance     int64  `json:"balance"`
	LastEntryID *int64 `json:"last_entry_id"`
}

// ⚠️ balance >= 0 是 CHECK，扣款扣穿会被数据库拒绝而不是写出负余额。
//
//	「余额不可提现」数据库强制不了 —— 它靠 ledger_accounts 里不存在
//	asset:bank ← liability:user_wallet 这条路径，且没有写提现代码。
func (q *Queries) UpsertWalletBalance(ctx context.Context, arg UpsertWalletBalanceParams) (WalletBalance, error) {
	row := q.db.QueryRow(ctx, upsertWalletBalance,
		arg.UserID,
		arg.Currency,
		arg.Balance,
		arg.LastEntryID,
	)
	var i WalletBalance
	err := row.Scan(
		&i.UserID,
		&i.Currency,
		&i.Balance,
		&i.LastEntryID,
		&i.UpdatedAt,
	)
	return i, err
}

